void read_font_to_mem(uint32_t *arr,int addr_st,/*MNT_OSD_FONT_TYPE_t sel,*/uint32_t arr_size){
    //size_t arr_size = WIN0_TYPE_IDX;
   // switch(sel) {
   //     case FONT_TYPE_1B : arr_size = FONT_1B_SIZE; break;
   //     case FONT_TYPE_2B : arr_size = FONT_2B_SIZE; break;
   //     case FONT_TYPE_4B : arr_size = FONT_4B_SIZE; break;
   //     case WIN0_TYPE_IDX: arr_size = WIN0_SIZE   ; break;
   //     case WIN1_TYPE_IDX: arr_size = WIN1_SIZE   ; break;
   //     case WIN2_TYPE_IDX: arr_size = WIN2_SIZE   ; break;
   //     case WIN3_TYPE_IDX: arr_size = WIN3_SIZE   ; break;
   //     case WIN4_TYPE_IDX: arr_size = WIN4_SIZE   ; break;
   //     case WIN5_TYPE_IDX: arr_size = WIN5_SIZE   ; break;
   //     case WIN6_TYPE_IDX: arr_size = WIN6_SIZE   ; break;
   //     case WIN7_TYPE_IDX: arr_size = WIN7_SIZE   ; break;
   //     default: printf("[cfg_share_mem] :share_mem_idx [%d] error,pls set again",sel);   
   // }                                              
    uint32_t value;

    cfg_ram_lut_addr(1,addr_st); 
    for(int i =0;i<arr_size;i++){
        value   = arr[i];
        cfg_ram_lut_data(1,value&0xffffffff);
    }
}

