void init_color_mem(MNT_OSD_COLOR_PALETTE_t* arr, int addr_st){

    uint32_t value;

    cfg_ram_lut_addr(0,addr_st); 
    for(int i =0;i<PALETTE_SIZE;i++){
        value   = (arr[i].u1ColorKey<<24)|(arr[i].u8Red<<16)|(arr[i].u8Green<<8)|(arr[i].u8Blue);
        cfg_ram_lut_data(0,value&0x1ffffff);
    }

}



void init_osd_win_font(MNT_OSD_t *mnt_vpu_osd)
{
    //strcpy(mnt_vpu_osd->osd_win_info.osd_win_idx_file[0] ,"/home/wenqiang.ge/work/project_ms1/ucode/vpu/osd_info/win0_idx.txt");
    //strcpy(mnt_vpu_osd->osd_win_info.osd_win_idx_file[1] ,"/home/wenqiang.ge/work/project_ms1/ucode/vpu/osd_info/win0_idx.txt");
    //strcpy(mnt_vpu_osd->osd_win_info.osd_win_idx_file[2] ,"/home/wenqiang.ge/work/project_ms1/ucode/vpu/osd_info/win0_idx.txt");
    //strcpy(mnt_vpu_osd->osd_win_info.osd_win_idx_file[3] ,"/home/wenqiang.ge/work/project_ms1/ucode/vpu/osd_info/win0_idx.txt");
    //strcpy(mnt_vpu_osd->osd_win_info.osd_win_idx_file[4] ,"/home/wenqiang.ge/work/project_ms1/ucode/vpu/osd_info/win0_idx.txt");
    //strcpy(mnt_vpu_osd->osd_win_info.osd_win_idx_file[5] ,"/home/wenqiang.ge/work/project_ms1/ucode/vpu/osd_info/win0_idx.txt");
    //strcpy(mnt_vpu_osd->osd_win_info.osd_win_idx_file[6] ,"/home/wenqiang.ge/work/project_ms1/ucode/vpu/osd_info/win0_idx.txt");
    //strcpy(mnt_vpu_osd->osd_win_info.osd_win_idx_file[7] ,"/home/wenqiang.ge/work/project_ms1/ucode/vpu/osd_info/win0_idx.txt");
    //strcpy(mnt_vpu_osd->osd_win_info.osd_1bit_font_file,"/home/wenqiang.ge/work/project_ms1/ucode/vpu/osd_info/1bit_font.txt");
    //strcpy(mnt_vpu_osd->osd_win_info.osd_2bit_font_file,"/home/wenqiang.ge/work/project_ms1/ucode/vpu/osd_info/2bit_font.txt");
    //strcpy(mnt_vpu_osd->osd_win_info.osd_4bit_font_file,"/home/wenqiang.ge/work/project_ms1/ucode/vpu/osd_info/4b_font.txt");
    //strcpy(mnt_vpu_osd->osd_win_info.osd_color_file    ,"/home/wenqiang.ge/work/project_ms1/ucode/vpu/osd_info/color_data.txt"       );
    

    

    mnt_vpu_osd->osd_win_info.osd_win_addr_st[0] = 0; 
    mnt_vpu_osd->osd_win_info.osd_win_lt_x[0]    = 5;
    mnt_vpu_osd->osd_win_info.osd_win_lt_y[0]    = 5;

    for(int i=0;i<FOSD_WIN_NUM;i++){
        mnt_vpu_osd->osd_win_info.osd_win_en[i]        = (i%FOSD_WIN_NUM==0);
        mnt_vpu_osd->osd_win_info.osd_win_vflip_en[i]  = 0;
        mnt_vpu_osd->osd_win_info.osd_win_hmirr_en[i]  = 0;
        mnt_vpu_osd->osd_win_info.osd_font_vflip_en[i] = 0;
        mnt_vpu_osd->osd_win_info.osd_font_hmirr_en[i] = 0;
        mnt_vpu_osd->osd_win_info.osd_blend_alpha[i]   = 0xff;

        mnt_vpu_osd->osd_win_info.osd_font_hnum[i]    = i==0 ? 56 : 0;
        mnt_vpu_osd->osd_win_info.osd_font_vnum[i]    = i==0 ? 26 : 0; 
        if(i>0){
            mnt_vpu_osd->osd_win_info.osd_win_lt_x[i]    = mnt_vpu_osd->osd_win_info.osd_win_lt_x[i-1]+mnt_vpu_osd->osd_win_info.osd_font_hnum[i-1]*FOSD_FONT_HNUM+5;
            mnt_vpu_osd->osd_win_info.osd_win_lt_y[i]    = mnt_vpu_osd->osd_win_info.osd_win_lt_y[i-1]+5;
        
            mnt_vpu_osd->osd_win_info.osd_win_addr_st[i] = mnt_vpu_osd->osd_win_info.osd_win_addr_st[i-1]+ mnt_vpu_osd->osd_win_info.osd_font_hnum[i-1]*mnt_vpu_osd->osd_win_info.osd_font_vnum[i-1];
        }
        mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_mode[i]  = 0;
        mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_alpha[i] = 0;
        mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_r[i]     = 0;
        mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_g[i]     = 0;
        mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_b[i]     = 0;
        mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_lt_x[i]  = 0;
        mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_lt_y[i]  = 0;
        mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_rb_x[i]  = 0;
        mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_rb_y[i]  = 0;
       
    }
    mnt_vpu_osd->osd_win_info.osd_win_rot_90        =  0;
    mnt_vpu_osd->osd_win_info.osd_win_rot_180       =  0;
    mnt_vpu_osd->osd_win_info.osd_win_rot_270       =  0;
    
    mnt_vpu_osd->osd_win_info.osd_2bit_font_idx_st_th = 512;
    mnt_vpu_osd->osd_win_info.osd_4bit_font_idx_st_th = 512+512;

    mnt_vpu_osd->osd_win_info.osd_1bit_font_addr_st =  mnt_vpu_osd->osd_win_info.osd_win_addr_st[FOSD_WIN_NUM-1]+ mnt_vpu_osd->osd_win_info.osd_font_hnum[FOSD_WIN_NUM-1]*mnt_vpu_osd->osd_win_info.osd_font_vnum[FOSD_WIN_NUM-1]+100;
    mnt_vpu_osd->osd_win_info.osd_2bit_font_addr_st =  mnt_vpu_osd->osd_win_info.osd_1bit_font_addr_st + (mnt_vpu_osd->osd_win_info.osd_2bit_font_idx_st_th*FOSD_FONT_HNUM*FOSD_FONT_VNUM)/FOSD_SHARE_RAM_WID;
    mnt_vpu_osd->osd_win_info.osd_4bit_font_addr_st =  mnt_vpu_osd->osd_win_info.osd_2bit_font_addr_st + ((mnt_vpu_osd->osd_win_info.osd_4bit_font_idx_st_th-mnt_vpu_osd->osd_win_info.osd_2bit_font_idx_st_th)*FOSD_FONT_HNUM*FOSD_FONT_VNUM*2)/FOSD_SHARE_RAM_WID;

    mnt_vpu_osd->osd_win_info.osd_font_repack_info.osd_font_rep_en             =  0;
    mnt_vpu_osd->osd_win_info.osd_font_repack_info.osd_font_gap                =  1;
    mnt_vpu_osd->osd_win_info.osd_font_repack_info.osd_font_rep_num            =  1;
    mnt_vpu_osd->osd_win_info.osd_font_repack_info.osd_font_nrep_num           =  1;
    for(int i=0;i<FOSD_FONT_REP_NUM;i++){
        mnt_vpu_osd->osd_win_info.osd_font_repack_info.osd_font_rep_st_addr[i]        =  0;
        mnt_vpu_osd->osd_win_info.osd_font_repack_info.osd_font_rep_sum_num[i]        =  0;
        mnt_vpu_osd->osd_win_info.osd_font_repack_info.osd_font_nrep_st_addr[i]        =  0;
        mnt_vpu_osd->osd_win_info.osd_font_repack_info.osd_font_nrep_sum_num[i]        =  0;
    }

}
void set_osd_win_font(MNT_OSD_t *mnt_vpu_osd)
{

// cfg 
    uint8_t  win_rot_en            = get_font_rot_info(mnt_vpu_osd);
    uint32_t font_type_2b_th       = mnt_vpu_osd->osd_win_info.osd_2bit_font_idx_st_th   ;
    uint32_t font_type_4b_th       = mnt_vpu_osd->osd_win_info.osd_4bit_font_idx_st_th   ;
    uint8_t  osd_win_invalid_en    = mnt_vpu_osd->osd_win_info.osd_win_invalid_en        ;
    uint8_t  osd_win_invalid_r     = mnt_vpu_osd->osd_win_info.osd_win_invalid_r         ;
    uint8_t  osd_win_invalid_g     = mnt_vpu_osd->osd_win_info.osd_win_invalid_g         ;
    uint8_t  osd_win_invalid_b     = mnt_vpu_osd->osd_win_info.osd_win_invalid_b         ;
    uint8_t  osd_win_invalid_alpha = mnt_vpu_osd->osd_win_info.osd_win_invalid_alpha     ;  

//init share_mem
    for(int i =0;i<FOSD_WIN_NUM;i++){
        cfg_win_en(i,mnt_vpu_osd->osd_win_info.osd_win_en[i]);
        cfg_win_alpha(i,mnt_vpu_osd->osd_win_info.osd_blend_alpha[i]);
        cfg_win_baseaddr(i,mnt_vpu_osd->osd_win_info.osd_win_addr_st[i]);
        cfg_win_position(i,mnt_vpu_osd->osd_win_info.osd_win_lt_x[i],mnt_vpu_osd->osd_win_info.osd_win_lt_y[i],mnt_vpu_osd->osd_win_info.osd_font_hnum[i],mnt_vpu_osd->osd_win_info.osd_font_vnum[i],win_rot_en);

    }
    if(mnt_vpu_osd->osd_win_info.osd_win_en[0]){
        read_font_to_mem(osd_win0_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[0],WIN0_SIZE);        
    }
    if(mnt_vpu_osd->osd_win_info.osd_win_en[1]){
        read_font_to_mem(osd_win1_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[1],WIN1_SIZE);        
    }
    if(mnt_vpu_osd->osd_win_info.osd_win_en[2]){
        read_font_to_mem(osd_win2_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[2],WIN2_SIZE);        
    }
    if(mnt_vpu_osd->osd_win_info.osd_win_en[3]){
        read_font_to_mem(osd_win3_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[3],WIN3_SIZE);        
    }
    if(mnt_vpu_osd->osd_win_info.osd_win_en[4]){
        read_font_to_mem(osd_win4_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[4],WIN4_SIZE);        
    }
    if(mnt_vpu_osd->osd_win_info.osd_win_en[5]){
        read_font_to_mem(osd_win5_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[5],WIN5_SIZE);        
    }
    if(mnt_vpu_osd->osd_win_info.osd_win_en[6]){
        read_font_to_mem(osd_win6_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[6],WIN6_SIZE);        
    }
    if(mnt_vpu_osd->osd_win_info.osd_win_en[7]){
        read_font_to_mem(osd_win7_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[7],WIN7_SIZE);        
    }

    cfg_font_baseaddr(FONT_TYPE_1B,mnt_vpu_osd->osd_win_info.osd_1bit_font_addr_st);
    cfg_font_baseaddr(FONT_TYPE_2B,mnt_vpu_osd->osd_win_info.osd_2bit_font_addr_st);
    cfg_font_baseaddr(FONT_TYPE_4B,mnt_vpu_osd->osd_win_info.osd_4bit_font_addr_st);
    cfg_win_font_ctrl(mnt_vpu_osd);    
    cfg_font_rot_ctrl(mnt_vpu_osd);
    printf("[OSD_DEBUG] :: cfg OSD win repack start\n");    
    if(mnt_vpu_osd->osd_win_info.osd_font_repack_info.osd_font_rep_en==1){
        cfg_font_repack(&mnt_vpu_osd->osd_win_info.osd_font_repack_info);        
    }
    else{
        read_font_to_mem(font_1b_arr,mnt_vpu_osd->osd_win_info.osd_1bit_font_addr_st,FONT_1B_SIZE);
    }
    printf("[OSD_DEBUG] :: cfg OSD win repack done\n");
    read_font_to_mem(font_2b_arr,mnt_vpu_osd->osd_win_info.osd_2bit_font_addr_st,FONT_2B_SIZE);
    read_font_to_mem(font_4b_arr,mnt_vpu_osd->osd_win_info.osd_4bit_font_addr_st,FONT_4B_SIZE); 
    init_color_mem(osd_color_palette,0);
    cfg_font_start_idx(FONT_TYPE_2B,font_type_2b_th);
    cfg_font_start_idx(FONT_TYPE_4B,font_type_4b_th);
    if(osd_win_invalid_en){
        cfg_win_invalid_area(osd_win_invalid_en,osd_win_invalid_r,osd_win_invalid_g,osd_win_invalid_b,osd_win_invalid_alpha);
    }


}

void update_osd_share_ram(MNT_OSD_t *mnt_vpu_osd, int upd_win_en, int upd_win_alpha ,int upd_win_baddr,int upd_font_baddr,int upd_font_th_st,int wait_update_en)
{

    // cfg 
    uint8_t  win_rot_en                         = get_font_rot_info(mnt_vpu_osd);
    uint32_t font_type_2b_th                    = mnt_vpu_osd->osd_win_info.osd_2bit_font_idx_st_th   ;
    uint32_t font_type_4b_th                    = mnt_vpu_osd->osd_win_info.osd_4bit_font_idx_st_th   ;
    uint8_t  osd_win_invalid_en                 = mnt_vpu_osd->osd_win_info.osd_win_invalid_en        ;
    uint8_t  osd_win_invalid_r                  = mnt_vpu_osd->osd_win_info.osd_win_invalid_r         ;
    uint8_t  osd_win_invalid_g                  = mnt_vpu_osd->osd_win_info.osd_win_invalid_g         ;
    uint8_t  osd_win_invalid_b                  = mnt_vpu_osd->osd_win_info.osd_win_invalid_b         ;
    uint8_t  osd_win_invalid_alpha              = mnt_vpu_osd->osd_win_info.osd_win_invalid_alpha     ;  
    uint8_t  osd_win_update_mode  = 0;
    uint8_t  osd_win_update_alpha = 0;
    uint8_t  osd_win_update_r     = 0;
    uint8_t  osd_win_update_g     = 0;
    uint8_t  osd_win_update_b     = 0;
    uint8_t  osd_win_update_lt_x  = 0;
    uint8_t  osd_win_update_lt_y  = 0;
    uint8_t  osd_win_update_rb_x  = 0;
    uint8_t  osd_win_update_rb_y  = 0;
                                                                                                                                  
    uint32_t osd_win_upd_rgb;
//init share_mem
    for(int i =0;i<FOSD_WIN_NUM;i++){ 
        osd_win_update_mode  = mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_mode[i] ;
        osd_win_update_alpha = mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_alpha[i];
        osd_win_update_r     = mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_r[i]    ;
        osd_win_update_g     = mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_g[i]    ;
        osd_win_update_b     = mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_b[i]    ;
        osd_win_update_lt_x  = mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_lt_x[i] ;
        osd_win_update_lt_y  = mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_lt_y[i] ;
        osd_win_update_rb_x  = mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_rb_x[i] ;
        osd_win_update_rb_y  = mnt_vpu_osd->osd_win_info.osd_win_update_info.osd_win_update_rb_y[i] ;
        if(FOSD_WIN_CLEAR_MODE==1){ 
            if(mnt_vpu_osd->osd_win_info.osd_win_en[i]){
                osd_win_upd_rgb = (osd_win_update_r<<16)|(osd_win_update_g<<8)|osd_win_update_b;
                clear_win_info(i,osd_win_update_mode,osd_win_update_alpha,osd_win_upd_rgb,osd_win_update_lt_x,osd_win_update_lt_y,osd_win_update_rb_x,osd_win_update_rb_y);
            }
            if(upd_win_en==1){
                cfg_win_en(i,mnt_vpu_osd->osd_win_info.osd_win_en[i]);
            }
        }
        else{
            cfg_win_en(i,0);
        }
        if(wait_update_en==1){
            if(FOSD_WIN_CLEAR_MODE==1){ 
                close_clear_win_info();
            }
            else{
                cfg_win_en(i,mnt_vpu_osd->osd_win_info.osd_win_en[i]);
            }
            if(upd_win_alpha==1){
                cfg_win_alpha(i,mnt_vpu_osd->osd_win_info.osd_blend_alpha[i]);
            }
            if(upd_win_baddr==1){
                cfg_win_baseaddr(i,mnt_vpu_osd->osd_win_info.osd_win_addr_st[i]);
            }
            if(mnt_vpu_osd->osd_win_info.osd_win_en[i]){
            cfg_win_position(i,mnt_vpu_osd->osd_win_info.osd_win_lt_x[i],mnt_vpu_osd->osd_win_info.osd_win_lt_y[i],mnt_vpu_osd->osd_win_info.osd_font_hnum[i],mnt_vpu_osd->osd_win_info.osd_font_vnum[i],win_rot_en);
            }
        }
        
    }
    if(wait_update_en==1){    
        if(mnt_vpu_osd->osd_win_info.osd_win_en[0]){
            read_font_to_mem(osd_win0_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[0],WIN0_SIZE);        
        }
        if(mnt_vpu_osd->osd_win_info.osd_win_en[1]){
            read_font_to_mem(osd_win1_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[1],WIN1_SIZE);        
        }
        if(mnt_vpu_osd->osd_win_info.osd_win_en[2]){
            read_font_to_mem(osd_win2_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[2],WIN2_SIZE);        
        }
        if(mnt_vpu_osd->osd_win_info.osd_win_en[3]){
            read_font_to_mem(osd_win3_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[3],WIN3_SIZE);        
        }
        if(mnt_vpu_osd->osd_win_info.osd_win_en[4]){
            read_font_to_mem(osd_win4_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[4],WIN4_SIZE);        
        }
        if(mnt_vpu_osd->osd_win_info.osd_win_en[5]){
            read_font_to_mem(osd_win5_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[5],WIN5_SIZE);        
        }
        if(mnt_vpu_osd->osd_win_info.osd_win_en[6]){
            read_font_to_mem(osd_win6_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[6],WIN6_SIZE);        
        }
        if(mnt_vpu_osd->osd_win_info.osd_win_en[7]){
            read_font_to_mem(osd_win7_idx_arr,mnt_vpu_osd->osd_win_info.osd_win_addr_st[7],WIN7_SIZE);        
        }
        if(upd_font_baddr){
            cfg_font_baseaddr(FONT_TYPE_1B,mnt_vpu_osd->osd_win_info.osd_1bit_font_addr_st);
            cfg_font_baseaddr(FONT_TYPE_2B,mnt_vpu_osd->osd_win_info.osd_2bit_font_addr_st);
            cfg_font_baseaddr(FONT_TYPE_4B,mnt_vpu_osd->osd_win_info.osd_4bit_font_addr_st);
        }
        cfg_win_font_ctrl(mnt_vpu_osd);    
        cfg_font_rot_ctrl(mnt_vpu_osd);
        read_font_to_mem(font_1b_arr,mnt_vpu_osd->osd_win_info.osd_1bit_font_addr_st,FONT_1B_SIZE);
        read_font_to_mem(font_2b_arr,mnt_vpu_osd->osd_win_info.osd_2bit_font_addr_st,FONT_2B_SIZE);
        read_font_to_mem(font_4b_arr,mnt_vpu_osd->osd_win_info.osd_4bit_font_addr_st,FONT_4B_SIZE); 
        if(upd_font_th_st){
            cfg_font_start_idx(FONT_TYPE_2B,font_type_2b_th);
            cfg_font_start_idx(FONT_TYPE_4B,font_type_4b_th);
        }
        if(osd_win_invalid_en){
            cfg_win_invalid_area(osd_win_invalid_en,osd_win_invalid_r,osd_win_invalid_g,osd_win_invalid_b,osd_win_invalid_alpha);
        }
    }
}

void init_osd_rect(MNT_OSD_t *mnt_vpu_osd)
{
    for(int i=0;i<FOSD_RECT_NUM;i++){
        mnt_vpu_osd->osd_rect_info.osd_rect_en[i]       =1;
        mnt_vpu_osd->osd_rect_info.osd_rect_st_x[i]     =80+i*10;
        mnt_vpu_osd->osd_rect_info.osd_rect_st_y[i]     =80+i*10;
        mnt_vpu_osd->osd_rect_info.osd_rect_w[i]        =80+i*10;
        mnt_vpu_osd->osd_rect_info.osd_rect_h[i]        =60+i*10;
        mnt_vpu_osd->osd_rect_info.osd_rect_thick[i]    =10+i;
        mnt_vpu_osd->osd_rect_info.osd_rect_grad_mode[i]= i==0 ? RECT_PURE :i==1 ? RECT_HORI_GRAD:i==2 ? RECT_HORI_CENTER_GRAD:i==3 ?RECT_VERT_GRAD:RECT_BILA_CENTER_GRAD;
        mnt_vpu_osd->osd_rect_info.osd_rect_mode[i]     =i>0;
        mnt_vpu_osd->osd_rect_info.osd_rect_step_r[i]   =2;
        mnt_vpu_osd->osd_rect_info.osd_rect_step_g[i]   =2;
        mnt_vpu_osd->osd_rect_info.osd_rect_step_b[i]   =2;
        mnt_vpu_osd->osd_rect_info.osd_rect_st_r[i]     =128-i*10;
        mnt_vpu_osd->osd_rect_info.osd_rect_st_g[i]     =100-i*10;
        mnt_vpu_osd->osd_rect_info.osd_rect_st_b[i]     =88-i*10;
        mnt_vpu_osd->osd_rect_info.osd_rect_ed_r[i]     =228-i*10;
        mnt_vpu_osd->osd_rect_info.osd_rect_ed_g[i]     =200-i*10;
        mnt_vpu_osd->osd_rect_info.osd_rect_ed_b[i]     =188-i*10;
        mnt_vpu_osd->osd_rect_info.osd_rect_alpha[i]    =0x1f;
    } 
        mnt_vpu_osd->osd_rect_info.osd_rect_invalid_en       =0;
        mnt_vpu_osd->osd_rect_info.osd_rect_invalid_r        =0;
        mnt_vpu_osd->osd_rect_info.osd_rect_invalid_g        =0;
        mnt_vpu_osd->osd_rect_info.osd_rect_invalid_b        =0;
        mnt_vpu_osd->osd_rect_info.osd_rect_invalid_alpha    =0;
        
}
void set_osd_rect(MNT_OSD_t *mnt_vpu_osd)
{
        uint8_t  osd_rect_en       =0;  
        uint32_t osd_rect_st_x     =0;  
        uint32_t osd_rect_st_y     =0;  
        uint32_t osd_rect_w        =0;  
        uint32_t osd_rect_h        =0;  
        uint32_t osd_rect_thick    =0;  
        MNT_OSD_RECT_GRAD_TYPE_t osd_rect_grad_mode=RECT_PURE;  
        uint8_t  osd_rect_mode     =0;  
        uint8_t  osd_rect_step_r   =0;  
        uint8_t  osd_rect_step_g   =0;  
        uint8_t  osd_rect_step_b   =0;  
        uint8_t  osd_rect_st_r     =0;  
        uint8_t  osd_rect_st_g     =0;  
        uint8_t  osd_rect_st_b     =0;  
        uint8_t  osd_rect_ed_r     =0;  
        uint8_t  osd_rect_ed_g     =0;  
        uint8_t  osd_rect_ed_b     =0;  
        uint8_t  osd_rect_alpha    =0;  
        uint8_t  osd_rect_invalid_en    = mnt_vpu_osd->osd_rect_info.osd_rect_invalid_en          ;
        uint8_t  osd_rect_invalid_r     = mnt_vpu_osd->osd_rect_info.osd_rect_invalid_r           ;
        uint8_t  osd_rect_invalid_g     = mnt_vpu_osd->osd_rect_info.osd_rect_invalid_g           ;
        uint8_t  osd_rect_invalid_b     = mnt_vpu_osd->osd_rect_info.osd_rect_invalid_b           ;
        uint8_t  osd_rect_invalid_alpha = mnt_vpu_osd->osd_rect_info.osd_rect_invalid_alpha       ;
    for(int i=0;i<FOSD_RECT_NUM;i++){
        osd_rect_en       = mnt_vpu_osd->osd_rect_info.osd_rect_en[i]       ;
        osd_rect_st_x     = mnt_vpu_osd->osd_rect_info.osd_rect_st_x[i]     ;
        osd_rect_st_y     = mnt_vpu_osd->osd_rect_info.osd_rect_st_y[i]     ;
        osd_rect_w        = mnt_vpu_osd->osd_rect_info.osd_rect_w[i]        ;
        osd_rect_h        = mnt_vpu_osd->osd_rect_info.osd_rect_h[i]        ;
        osd_rect_thick    = mnt_vpu_osd->osd_rect_info.osd_rect_thick[i]    ;
        osd_rect_grad_mode= mnt_vpu_osd->osd_rect_info.osd_rect_grad_mode[i];
        osd_rect_mode     = mnt_vpu_osd->osd_rect_info.osd_rect_mode[i]     ;
        osd_rect_step_r   = mnt_vpu_osd->osd_rect_info.osd_rect_step_r[i]   ;
        osd_rect_step_g   = mnt_vpu_osd->osd_rect_info.osd_rect_step_g[i]   ;
        osd_rect_step_b   = mnt_vpu_osd->osd_rect_info.osd_rect_step_b[i]   ;
        osd_rect_st_r     = mnt_vpu_osd->osd_rect_info.osd_rect_st_r[i]     ;
        osd_rect_st_g     = mnt_vpu_osd->osd_rect_info.osd_rect_st_g[i]     ;
        osd_rect_st_b     = mnt_vpu_osd->osd_rect_info.osd_rect_st_b[i]     ;
        osd_rect_ed_r     = mnt_vpu_osd->osd_rect_info.osd_rect_ed_r[i]     ;
        osd_rect_ed_g     = mnt_vpu_osd->osd_rect_info.osd_rect_ed_g[i]     ;
        osd_rect_ed_b     = mnt_vpu_osd->osd_rect_info.osd_rect_ed_b[i]     ;
        osd_rect_alpha    = mnt_vpu_osd->osd_rect_info.osd_rect_alpha[i]    ;
        cfg_rect_en(i,osd_rect_en);
        cfg_rect_position(i,osd_rect_st_x,osd_rect_st_y,osd_rect_w,osd_rect_h);
        cfg_rect_mode_info(i,osd_rect_grad_mode,osd_rect_mode,osd_rect_thick,osd_rect_st_r,osd_rect_st_g,osd_rect_st_b,osd_rect_ed_r,osd_rect_ed_g,osd_rect_ed_b,osd_rect_alpha,osd_rect_w,osd_rect_h,osd_rect_step_r,osd_rect_step_g,osd_rect_step_b);
        
    }
    if(osd_rect_invalid_en) {
        cfg_rect_invalid_area(osd_rect_invalid_en,osd_rect_invalid_r,osd_rect_invalid_g,osd_rect_invalid_b,osd_rect_invalid_alpha);
    }
}

