void init_vpu_osd(MNT_OSD_t *mnt_vpu_osd)
{
    init_osd_win_font(mnt_vpu_osd);
    init_osd_rect(mnt_vpu_osd);
    init_osd_ellip(mnt_vpu_osd);
    init_osd_line(mnt_vpu_osd);
    printf("[OSD_DEBUG] :: init OSD done\n");
    
}

void set_vpu_osd(MNT_OSD_t *mnt_vpu_osd)
{
        set_osd_en(mnt_vpu_osd->osd_en);
    if(mnt_vpu_osd->osd_en) {
        set_osd_win_font(mnt_vpu_osd);
        set_osd_rect(mnt_vpu_osd);
        set_osd_ellip(mnt_vpu_osd);
        set_osd_line(mnt_vpu_osd);
        printf("[OSD_DEBUG] :: cfg OSD done\n");

        //Wr_reg_bits(FOSD_MODE_INFO_1_0  , 3, 15, 2);//RECT&LINE ENABLE
        //Wr_reg_bits(FOSD_WIN_FONT_INFO_0, 1, 30, 1);//FOSD      ENABLE
    } else {
        Wr_reg_bits(VPU_PROC_BLD_EN, 0, 0, 1);//BLEND CLOSE
        printf("[OSD_DEBUG] :: warnning not enable OSD \n");
//
    }
}
void set_osd_en(int osd_en){
    uint32_t osd_en_addr = FOSD_FRM_CTRL;
    Wr(osd_en_addr,(osd_en&0x1));
}

void cfg_win_font_ctrl(MNT_OSD_t *mnt_vpu_osd ){
    uint8_t osd_win_rot_90  = mnt_vpu_osd->osd_win_info.osd_win_rot_90  &0x1;
    uint8_t osd_win_rot_180 = mnt_vpu_osd->osd_win_info.osd_win_rot_180 &0x1;
    uint8_t osd_win_rot_270 = mnt_vpu_osd->osd_win_info.osd_win_rot_270 &0x1;
    uint8_t osd_win_rot_en  = osd_win_rot_90|osd_win_rot_180|osd_win_rot_270;
    
    uint8_t osd_win_en [FOSD_WIN_NUM]       ;
    uint8_t osd_win_vflip_en [FOSD_WIN_NUM] ;
    uint8_t osd_win_hmirr_en [FOSD_WIN_NUM] ;
    uint8_t osd_font_vflip_en [FOSD_WIN_NUM];
    uint8_t osd_font_hmirr_en [FOSD_WIN_NUM];

    uint32_t osd_win_rot_mode = osd_win_rot_90 ? 1 : osd_win_rot_180 ? 2: osd_win_rot_270 ? 3 : 0 ;
    uint32_t osd_win_info_addr = 0;
    for (int i=0;i<FOSD_WIN_NUM;i++){
        osd_win_en [i]        = mnt_vpu_osd->osd_win_info.osd_win_en[i];
        osd_win_vflip_en [i]  = mnt_vpu_osd->osd_win_info.osd_win_vflip_en[i];
        osd_win_hmirr_en [i]  = mnt_vpu_osd->osd_win_info.osd_win_hmirr_en[i];
        osd_font_vflip_en [i] = mnt_vpu_osd->osd_win_info.osd_font_vflip_en[i];
        osd_font_hmirr_en [i] = mnt_vpu_osd->osd_win_info.osd_font_hmirr_en[i];
        if(osd_win_rot_en){
            osd_win_vflip_en [i]  = 0;
            osd_win_hmirr_en [i]  = 0;
            osd_font_vflip_en [i] = 0;
            osd_font_hmirr_en [i] = 0;
        }
        else{// Font ctrl align To win ctrl
            osd_font_vflip_en [i] = osd_win_vflip_en [i];
            osd_font_hmirr_en [i] = osd_win_hmirr_en [i];       
        } 
        cfg_win_en(i,osd_win_en[i]);        
        osd_win_info_addr = i ==0 ? FOSD_WIN_FONT_INFO_0 : 
                            i ==1 ? FOSD_WIN_FONT_INFO_1 :
                            i ==2 ? FOSD_WIN_FONT_INFO_2 :
                            i ==3 ? FOSD_WIN_FONT_INFO_3 :
                            i ==4 ? FOSD_WIN_FONT_INFO_4 :
                            i ==5 ? FOSD_WIN_FONT_INFO_5 :
                            i ==6 ? FOSD_WIN_FONT_INFO_6 :
                                    FOSD_WIN_FONT_INFO_7 ;
        Wr_reg_bits(osd_win_info_addr,  ((osd_win_rot_mode<<6    )|
                                         (osd_font_vflip_en[i]<<5)|
                                         (osd_font_hmirr_en[i]<<4)|
                                         (osd_win_rot_mode<<2    )|
                                         (osd_win_vflip_en[i]<<1 )|
                                         (osd_win_hmirr_en[i]<<0 )),0,8); 

    }
    
}
uint8_t get_font_rot_info(MNT_OSD_t *mnt_vpu_osd ){
    uint8_t osd_win_rot_90  = mnt_vpu_osd->osd_win_info.osd_win_rot_90  &0x1;
    uint8_t osd_win_rot_180 = mnt_vpu_osd->osd_win_info.osd_win_rot_180 &0x1;
    uint8_t osd_win_rot_270 = mnt_vpu_osd->osd_win_info.osd_win_rot_270 &0x1;
    uint8_t osd_win_rot_en  = (osd_win_rot_90|osd_win_rot_270) &0x1;
    return osd_win_rot_en;
};

