void cfg_win_invalid_area(uint8_t en ,uint8_t color_r,uint8_t color_g,uint8_t color_b,uint8_t color_alpha ){
    uint32_t color_data = (color_alpha<<24)|(color_r<<16)|(color_g<<8)|color_b;
    if(en) Wr(FOSD_WIN_INVALID_AREA_RGBA,color_data);
};

void cfg_rect_invalid_area(uint8_t en ,uint8_t color_r,uint8_t color_g,uint8_t color_b,uint8_t color_alpha ){
    uint32_t color_data = (color_alpha<<24)|(color_r<<16)|(color_g<<8)|color_b;
    if(en) Wr(FOSD_RECT_INVALID_AREA_RGBA,color_data);
};

void cfg_line_invalid_area(uint8_t en ,uint8_t color_r,uint8_t color_g,uint8_t color_b,uint8_t color_alpha ){
    uint32_t color_data = (color_alpha<<24)|(color_r<<16)|(color_g<<8)|color_b;
    if(en) Wr(FOSD_LINE_INVALID_AREA_RGBA,color_data);
};
void cfg_font_rot_ctrl(MNT_OSD_t *mnt_vpu_osd ){
    uint8_t osd_win_rot_en =0;
    osd_win_rot_en = get_font_rot_info(mnt_vpu_osd);
    Wr(FOSD_FONT_ROTATE_CTRL,osd_win_rot_en);
};

void cfg_win_en(int win_idx, uint8_t win_en ){
    uint32_t win_addr =0;
    switch(win_idx) {
        case 0: win_addr = FOSD_WIN_FONT_INFO_0; break;
        case 1: win_addr = FOSD_WIN_FONT_INFO_1; break;
        case 2: win_addr = FOSD_WIN_FONT_INFO_2; break;
        case 3: win_addr = FOSD_WIN_FONT_INFO_3; break;
        case 4: win_addr = FOSD_WIN_FONT_INFO_4; break;
        case 5: win_addr = FOSD_WIN_FONT_INFO_5; break;
        case 6: win_addr = FOSD_WIN_FONT_INFO_6; break;
        case 7: win_addr = FOSD_WIN_FONT_INFO_7; break; 
        default: printf("[cfg_win_en] :win_idx [%d] error,pls set again",win_idx);   
    }
    Wr_reg_bits(win_addr,win_en,30,1);
};

