void osd_font_local_update(MNT_OSD_FONT_TYPE_t font_type,uint32_t *share_ram_arr,int font_new_addr,int arr_size){
    uint8_t  osd_win_update_fifo_en     = 1;
    uint8_t  osd_win_update_fifo_mode   = 0;
    uint32_t osd_win_addr               = 0;
    uint32_t osd_font_type_addr         = 0;
    switch(font_type){
        case (FONT_TYPE_1B) : osd_font_type_addr = FOSD_FONT_1BIT_ADDR;break;
        case (FONT_TYPE_2B) : osd_font_type_addr = FOSD_FONT_2BIT_ADDR;break;
        case (FONT_TYPE_4B) : osd_font_type_addr = FOSD_FONT_4BIT_ADDR;break;
        default: printf("[osd_font_local_update] :win_idx [%d] error,pls set again",font_type);     
    }
    Wr(FOSD_RAM_UPD_CRTL,(osd_win_update_fifo_mode<<1)|osd_win_update_fifo_en);          
    read_font_to_mem(share_ram_arr,font_new_addr,arr_size); 
    Wr(osd_font_type_addr,font_new_addr);
    //Wr(FOSD_RAM_UPD_CRTL,0);        
}
void osd_win_idx_local_update(int win_idx, uint32_t *share_ram_arr,int win_new_addr,int arr_size){
    uint8_t  osd_win_update_fifo_en     = 1;
    uint8_t  osd_win_update_fifo_mode   = 0;
    uint32_t osd_win_addr               = 0;
    Wr(FOSD_RAM_UPD_CRTL,(osd_win_update_fifo_mode<<1)|osd_win_update_fifo_en);
    MNT_OSD_FONT_TYPE_t win_idx_type = WIN0_TYPE_IDX;
    switch(win_idx) {
        case 0: {win_idx_type = WIN0_TYPE_IDX; 
                 osd_win_addr = FOSD_WIN_FONT_INFO_0; 
                break;}
        case 1: {win_idx_type = WIN1_TYPE_IDX; 
                 osd_win_addr = FOSD_WIN_FONT_INFO_1; 
                break;}
        case 2: {win_idx_type = WIN2_TYPE_IDX; 
                 osd_win_addr = FOSD_WIN_FONT_INFO_2; 
                break;}
        case 3: {win_idx_type = WIN3_TYPE_IDX; 
                 osd_win_addr = FOSD_WIN_FONT_INFO_3; 
                break;}
        case 4: {win_idx_type = WIN4_TYPE_IDX; 
                 osd_win_addr = FOSD_WIN_FONT_INFO_4; 
                break;}
        case 5: {win_idx_type = WIN5_TYPE_IDX; 
                 osd_win_addr = FOSD_WIN_FONT_INFO_5; 
                break;}
        case 6: {win_idx_type = WIN6_TYPE_IDX; 
                 osd_win_addr = FOSD_WIN_FONT_INFO_6; 
                break;}
        case 7: {win_idx_type = WIN7_TYPE_IDX; 
                 osd_win_addr = FOSD_WIN_FONT_INFO_7; 
                break;}    
        default: printf("[osd_win_idx_local_update] :win_idx [%d] error,pls set again",win_idx);     
    }              
    read_font_to_mem(share_ram_arr,win_new_addr,arr_size); 
    Wr_reg_bits(osd_win_addr,win_new_addr,16,14);
    //Wr(FOSD_RAM_UPD_CRTL,0);        
}
void osd_color_ram_local_update(MNT_OSD_COLOR_PALETTE_t *color_ram_arr, int color_new_addr){
    uint8_t osd_win_update_fifo_en     = 1;
    uint8_t osd_win_update_fifo_mode   = 1;
    Wr(FOSD_RAM_UPD_CRTL,(osd_win_update_fifo_mode<<1)|osd_win_update_fifo_en);
    init_color_mem(color_ram_arr,color_new_addr);
    //Wr(FOSD_RAM_UPD_CRTL,(osd_win_update_fifo_mode<<1)|0);//dont close mode 
}
void cfg_osd_win_crop_mode(int win_idx,int hofst, int vofst, int stride,int win_st_x,int win_st_y,int font_hnum,int font_vnum,int rot_en){
    uint32_t win_idx_ofst_addr    = 0;
    uint32_t win_st_xy_addr       = 0;
    uint32_t win_ed_xy_addr       = 0;
    uint32_t win_font_num_addr    = 0;
    uint32_t win_idx_stride_addr  = 0;
    uint32_t win_idx_crop_en      = 1;

    uint32_t win_ed_x             = win_st_x+font_hnum*(rot_en ? FOSD_FONT_VNUM : FOSD_FONT_HNUM)-1;
    uint32_t win_ed_y             = win_st_y+font_vnum*(rot_en ? FOSD_FONT_HNUM : FOSD_FONT_VNUM)-1;
    switch(win_idx) {
        case 0: {win_idx_ofst_addr   = FOSD_WIN_IDX_OFST_0  ; 
                 win_idx_stride_addr = FOSD_WIN_IDX_STRIDE_0;
                 win_st_xy_addr      = FOSD_WIN_LT_XY_0     ;
                 win_ed_xy_addr      = FOSD_WIN_RB_XY_0     ;
                 win_font_num_addr   = FOSD_WIN_WH_0        ;
        break;}
        case 1: {win_idx_ofst_addr   = FOSD_WIN_IDX_OFST_1  ; 
                 win_idx_stride_addr = FOSD_WIN_IDX_STRIDE_1;
                 win_st_xy_addr      = FOSD_WIN_LT_XY_1     ;
                 win_ed_xy_addr      = FOSD_WIN_RB_XY_1     ;
                 win_font_num_addr   = FOSD_WIN_WH_1        ;
        break;}
        case 2: {win_idx_ofst_addr   = FOSD_WIN_IDX_OFST_2  ; 
                 win_idx_stride_addr = FOSD_WIN_IDX_STRIDE_2;
                 win_st_xy_addr      = FOSD_WIN_LT_XY_2     ;
                 win_ed_xy_addr      = FOSD_WIN_RB_XY_2     ;
                 win_font_num_addr   = FOSD_WIN_WH_2        ;
        break;}
        case 3: {win_idx_ofst_addr   = FOSD_WIN_IDX_OFST_3  ; 
                 win_idx_stride_addr = FOSD_WIN_IDX_STRIDE_3;
                 win_st_xy_addr      = FOSD_WIN_LT_XY_3     ;
                 win_ed_xy_addr      = FOSD_WIN_RB_XY_3     ;
                 win_font_num_addr   = FOSD_WIN_WH_3        ;
        break;}
        case 4: {win_idx_ofst_addr   = FOSD_WIN_IDX_OFST_4  ; 
                 win_idx_stride_addr = FOSD_WIN_IDX_STRIDE_4;
                 win_st_xy_addr      = FOSD_WIN_LT_XY_4     ;
                 win_ed_xy_addr      = FOSD_WIN_RB_XY_4     ;
                 win_font_num_addr   = FOSD_WIN_WH_4        ;
        break;}
        case 5: {win_idx_ofst_addr   = FOSD_WIN_IDX_OFST_5  ; 
                 win_idx_stride_addr = FOSD_WIN_IDX_STRIDE_5;
                 win_st_xy_addr      = FOSD_WIN_LT_XY_5     ;
                 win_ed_xy_addr      = FOSD_WIN_RB_XY_5     ;
                 win_font_num_addr   = FOSD_WIN_WH_5        ;
        break;}
        case 6: {win_idx_ofst_addr   = FOSD_WIN_IDX_OFST_6  ; 
                 win_idx_stride_addr = FOSD_WIN_IDX_STRIDE_6;
                 win_st_xy_addr      = FOSD_WIN_LT_XY_6     ;
                 win_ed_xy_addr      = FOSD_WIN_RB_XY_6     ;
                 win_font_num_addr   = FOSD_WIN_WH_6        ;
        break;}
        case 7: {win_idx_ofst_addr   = FOSD_WIN_IDX_OFST_7  ; 
                 win_idx_stride_addr = FOSD_WIN_IDX_STRIDE_7;
                 win_st_xy_addr      = FOSD_WIN_LT_XY_7     ;
                 win_ed_xy_addr      = FOSD_WIN_RB_XY_7     ;
                 win_font_num_addr   = FOSD_WIN_WH_7        ;
        break;}    
        default: printf("[cfg_osd_win_crop_mode] :win_idx [%d] error,pls set again",win_idx);     
    }   
    Wr(win_idx_ofst_addr,(win_idx_crop_en<<26)|(hofst<<13)|vofst);
    Wr(win_idx_stride_addr,stride);
    Wr(win_st_xy_addr,(win_st_x<<13)|win_st_y);
    Wr(win_ed_xy_addr,(win_ed_x<<13)|win_ed_y);
    Wr(win_font_num_addr,(font_hnum<<13)|font_vnum);
}
void clear_win_info(int win_idx, int clear_local_win, int win_alpha, int win_color_rgb,int win_st_x, int win_st_y ,int win_ed_x, int win_ed_y){
    uint32_t win_clear_st_addr   = 0;
    uint32_t win_clear_ed_addr   = 0;
    uint32_t win_clear_rgba_addr = 0;
    uint32_t win_clear_ctrl_addr = FOSD_FONT_UPDATE_CRTL;
    uint8_t  win_clear_mode      = (clear_local_win ==1) <<win_idx;
    uint8_t  win_clear_en        = 1 <<win_idx;
    switch(win_idx){
        case 0 : {win_clear_st_addr   = FOSD_FONT_UPDATE_LT_XY_0;
                  win_clear_ed_addr   = FOSD_FONT_UPDATE_RB_XY_0;
                  win_clear_rgba_addr = FOSD_FONT_UPDATE_RGBA_0 ;
        break;}
        case 1 : {win_clear_st_addr   = FOSD_FONT_UPDATE_LT_XY_1;
                  win_clear_ed_addr   = FOSD_FONT_UPDATE_RB_XY_1;
                  win_clear_rgba_addr = FOSD_FONT_UPDATE_RGBA_1 ;
        break;}
        case 2 : {win_clear_st_addr   = FOSD_FONT_UPDATE_LT_XY_2;
                  win_clear_ed_addr   = FOSD_FONT_UPDATE_RB_XY_2;
                  win_clear_rgba_addr = FOSD_FONT_UPDATE_RGBA_2 ;
        break;}
        case 3 : {win_clear_st_addr   = FOSD_FONT_UPDATE_LT_XY_3;
                  win_clear_ed_addr   = FOSD_FONT_UPDATE_RB_XY_3;
                  win_clear_rgba_addr = FOSD_FONT_UPDATE_RGBA_3 ;
        break;}
        case 4 : {win_clear_st_addr   = FOSD_FONT_UPDATE_LT_XY_4;
                  win_clear_ed_addr   = FOSD_FONT_UPDATE_RB_XY_4;
                  win_clear_rgba_addr = FOSD_FONT_UPDATE_RGBA_4 ;
        break;}
        case 5 : {win_clear_st_addr   = FOSD_FONT_UPDATE_LT_XY_5;
                  win_clear_ed_addr   = FOSD_FONT_UPDATE_RB_XY_5;
                  win_clear_rgba_addr = FOSD_FONT_UPDATE_RGBA_5 ;
        break;}
        case 6 : {win_clear_st_addr   = FOSD_FONT_UPDATE_LT_XY_6;
                  win_clear_ed_addr   = FOSD_FONT_UPDATE_RB_XY_6;
                  win_clear_rgba_addr = FOSD_FONT_UPDATE_RGBA_6 ;
        break;}
        case 7 : {win_clear_st_addr   = FOSD_FONT_UPDATE_LT_XY_7;
                  win_clear_ed_addr   = FOSD_FONT_UPDATE_RB_XY_7;
                  win_clear_rgba_addr = FOSD_FONT_UPDATE_RGBA_7 ;
        break;}
        default: printf("[clear_win_info] :win_idx [%d] error,pls set again",win_idx);     
    }
    if(clear_local_win){
        Wr(win_clear_st_addr,(win_st_x<<13)|win_st_y);
        Wr(win_clear_ed_addr,(win_ed_x<<13)|win_ed_y);
    }
    Wr(win_clear_rgba_addr,(win_alpha<<24)|win_color_rgb);
    uint32_t win_clear_data = Rd(win_clear_ctrl_addr);
             win_clear_data = win_clear_data |((win_clear_en<<8)|win_clear_mode);
    Wr(win_clear_ctrl_addr,win_clear_data);
    

}
void close_clear_win_info(){
    uint32_t win_clear_ctrl_addr = FOSD_FONT_UPDATE_CRTL;
    Wr(win_clear_ctrl_addr,0);
    

}
void cfg_win_position(int win_idx, int win_st_x, int win_st_y,int font_hnum, int font_vnum ,uint8_t rot_en){

    uint32_t win_font_hnum  = rot_en ? font_vnum : font_hnum;
    uint32_t win_font_vnum  = rot_en ? font_hnum : font_vnum;
    uint32_t win_font_hsize = rot_en ? FOSD_FONT_VNUM : FOSD_FONT_HNUM;
    uint32_t win_font_vsize = rot_en ? FOSD_FONT_HNUM : FOSD_FONT_VNUM;

    uint32_t win_ed_x      = win_st_x+ win_font_hnum*win_font_hsize-1;
    uint32_t win_ed_y      = win_st_y+ win_font_vnum*win_font_vsize-1;

    uint32_t win_lt_addr =0;
    uint32_t win_rb_addr =0;
    uint32_t win_wh_addr =0;
    switch(win_idx) {
        case 0: {win_lt_addr = FOSD_WIN_LT_XY_0;
                 win_rb_addr = FOSD_WIN_RB_XY_0; 
                 win_wh_addr = FOSD_WIN_WH_0   ; 
        break;}
        case 1: {win_lt_addr = FOSD_WIN_LT_XY_1;
                 win_rb_addr = FOSD_WIN_RB_XY_1; 
                 win_wh_addr = FOSD_WIN_WH_1   ; 
        break;}
        case 2: {win_lt_addr = FOSD_WIN_LT_XY_2;
                 win_rb_addr = FOSD_WIN_RB_XY_2; 
                 win_wh_addr = FOSD_WIN_WH_2   ; 
        break;}
        case 3: {win_lt_addr = FOSD_WIN_LT_XY_3;
                 win_rb_addr = FOSD_WIN_RB_XY_3; 
                 win_wh_addr = FOSD_WIN_WH_3   ; 
        break;}
        case 4: {win_lt_addr = FOSD_WIN_LT_XY_4;
                 win_rb_addr = FOSD_WIN_RB_XY_4; 
                 win_wh_addr = FOSD_WIN_WH_4   ; 
        break;}
        case 5: {win_lt_addr = FOSD_WIN_LT_XY_5;
                 win_rb_addr = FOSD_WIN_RB_XY_5; 
                 win_wh_addr = FOSD_WIN_WH_5   ; 
        break;}
        case 6: {win_lt_addr = FOSD_WIN_LT_XY_6;
                 win_rb_addr = FOSD_WIN_RB_XY_6; 
                 win_wh_addr = FOSD_WIN_WH_6   ; 
        break;}
        case 7: {win_lt_addr = FOSD_WIN_LT_XY_7;
                 win_rb_addr = FOSD_WIN_RB_XY_7; 
                 win_wh_addr = FOSD_WIN_WH_7   ; 
        break;}
        default: printf("[cfg_win_position] win_idx [%d] error,pls set again",win_idx);   
    }
    Wr(win_lt_addr,(win_st_x<<13)|(win_st_y<<0));
    Wr(win_rb_addr,(win_ed_x<<13)|(win_ed_y<<0));
    Wr(win_wh_addr,(font_hnum<<13)|(font_vnum<<0));
}; 

void cfg_font_baseaddr(MNT_OSD_FONT_TYPE_t font_type, int font_baddr ){
    uint32_t font_addr =0;
    switch(font_type) {
        case FONT_TYPE_1B: font_addr = FOSD_FONT_1BIT_ADDR; break;
        case FONT_TYPE_2B: font_addr = FOSD_FONT_2BIT_ADDR; break;
        case FONT_TYPE_4B: font_addr = FOSD_FONT_4BIT_ADDR; break;
        default: printf("[cfg_font_addr] :Font_type [%d] error,pls set again",font_type);   
    }
    Wr(font_addr,font_baddr);
}; 

void cfg_font_start_idx(MNT_OSD_FONT_TYPE_t font_type, int font_st_idx ){

    switch(font_type) {    
        case FONT_TYPE_2B: Wr_reg_bits(FOSD_FONT_IDX_TH,font_st_idx,12,12); break;
        case FONT_TYPE_4B: Wr_reg_bits(FOSD_FONT_IDX_TH,font_st_idx,0 ,12); break;
        default: printf("[cfg_font_th] :Font_type [%d] error,pls set again",font_type);   
    }
}; 


void cfg_ram_lut_addr(uint8_t is_share_ram, int buf_addr ){
    uint32_t ram_addr =0;
    switch(is_share_ram) {    
        case 1: ram_addr = FOSD_SHARE_RAM_ADDR; break;
        case 0: ram_addr = FOSD_COLOR_RAM_ADDR; break;
        default: printf("[cfg_ram_addr] :ram_type [%d] error,pls set again",is_share_ram);   
    }
    Wr(ram_addr,buf_addr);
};

void cfg_ram_lut_data(uint8_t is_share_ram, int buf_data ){
    uint32_t ram_addr =0;
    switch(is_share_ram) {    
        case 1: ram_addr = FOSD_SHARE_RAM_DATA; break;
        case 0: ram_addr = FOSD_COLOR_RAM_DATA; break;
        default: printf("[cfg_ram_data] :ram_type [%d] error,pls set again",is_share_ram);   
    }
    Wr(ram_addr,buf_data);
}; 

void cfg_rect_en(int rect_idx, uint8_t rect_en ){
    uint32_t rect_addr =0;
    switch(rect_idx) {
        case 0: rect_addr = FOSD_MODE_INFO_1_0; break;
        case 1: rect_addr = FOSD_MODE_INFO_1_1; break;
        case 2: rect_addr = FOSD_MODE_INFO_1_2; break;
        case 3: rect_addr = FOSD_MODE_INFO_1_3; break;
        case 4: rect_addr = FOSD_MODE_INFO_1_4; break;
        default: printf("[cfg_rect_en] :rect_idx [%d] error,pls set again",rect_idx);   
    }
    Wr_reg_bits(rect_addr,rect_en,11,1);
};

void cfg_rect_position(int rect_idx, int rect_st_x, int rect_st_y, int rect_width, int rect_height  ){
    uint32_t rect_xy_addr =0;
    uint32_t rect_wh_addr =0;
    switch(rect_idx) {
        case 0: {rect_xy_addr = FOSD_RECT_XY_0;
                 rect_wh_addr = FOSD_RECT_WH_0; 
        break;}
        case 1: {rect_xy_addr = FOSD_RECT_XY_1;
                 rect_wh_addr = FOSD_RECT_WH_1; 
        break;}
        case 2: {rect_xy_addr = FOSD_RECT_XY_2;
                 rect_wh_addr = FOSD_RECT_WH_2; 
        break;}
        case 3: {rect_xy_addr = FOSD_RECT_XY_3;
                 rect_wh_addr = FOSD_RECT_WH_3; 
        break;}
        case 4: {rect_xy_addr = FOSD_RECT_XY_4;
                 rect_wh_addr = FOSD_RECT_WH_4; 
        break;}
        default: printf("[cfg_rect_position] :rect_idx [%d] error,pls set again",rect_idx);   
    }
    Wr(rect_xy_addr,(rect_st_x<<13)|(rect_st_y));
    Wr(rect_wh_addr,(rect_width<<13)|(rect_width));
};

void cfg_rect_mode_info(int rect_idx, MNT_OSD_RECT_GRAD_TYPE_t rect_grad_mode, int rect_mode, int rect_thick, int rect_st_r ,int rect_st_g ,int rect_st_b ,int rect_ed_r ,int rect_ed_g ,int rect_ed_b ,int rect_alpha,int rect_width ,int rect_height ,int step_r,int step_g ,int step_b  ){
    uint32_t rect_mode_addr  =0;
    uint32_t rect_delta_addr =0;
    uint32_t rect_step_addr  =0;
    uint32_t rect_color_addr =0;
    uint8_t  rect_grad_en    = (rect_mode ==1)&0x1;
    uint32_t rect_grad_mode_val  = 0;
    uint32_t rect_line_thick     = 0;

    uint32_t color_r_delta       = rect_ed_r>rect_st_r ? rect_ed_r-rect_st_r : rect_st_r-rect_ed_r;
    uint32_t color_g_delta       = rect_ed_g>rect_st_g ? rect_ed_g-rect_st_g : rect_st_g-rect_ed_g;
    uint32_t color_b_delta       = rect_ed_b>rect_st_b ? rect_ed_b-rect_st_b : rect_st_b-rect_ed_b;
    uint32_t rect_length         = rect_width > rect_height ?  rect_height : rect_width;
    uint32_t comp_r              = rect_ed_r>rect_st_r ? 0 : 1;            
    uint32_t comp_g              = rect_ed_g>rect_st_g ? 0 : 1;            
    uint32_t comp_b              = rect_ed_b>rect_st_b ? 0 : 1;            
    uint32_t delta_r             = 0;            
    uint32_t delta_g             = 0;            
    uint32_t delta_b             = 0;

            
    switch(rect_idx) {
        case 0: {rect_mode_addr  = FOSD_MODE_INFO_1_0;
                 rect_delta_addr = FOSD_RECT_DELTA_0 ; 
                 rect_step_addr  = FOSD_RECT_STEP_0  ; 
                 rect_color_addr = FOSD_RECT_RGBA_0  ; 
        break;}
        case 1: {rect_mode_addr  = FOSD_MODE_INFO_1_1;
                 rect_delta_addr = FOSD_RECT_DELTA_1 ; 
                 rect_step_addr  = FOSD_RECT_STEP_1  ; 
                 rect_color_addr = FOSD_RECT_RGBA_1  ; 
        break;}
        case 2: {rect_mode_addr  = FOSD_MODE_INFO_1_2;
                 rect_delta_addr = FOSD_RECT_DELTA_2 ; 
                 rect_step_addr  = FOSD_RECT_STEP_2  ; 
                 rect_color_addr = FOSD_RECT_RGBA_2  ; 
        break;}
        case 3: {rect_mode_addr  = FOSD_MODE_INFO_1_3;
                 rect_delta_addr = FOSD_RECT_DELTA_3 ; 
                 rect_step_addr  = FOSD_RECT_STEP_3  ; 
                 rect_color_addr = FOSD_RECT_RGBA_3  ; 
        break;}
        case 4: {rect_mode_addr  = FOSD_MODE_INFO_1_4;
                 rect_delta_addr = FOSD_RECT_DELTA_4 ; 
                 rect_step_addr  = FOSD_RECT_STEP_4  ; 
                 rect_color_addr = FOSD_RECT_RGBA_4  ; 
        break;}
        default: printf("[cfg_rect_mode_info] :rect_idx [%d] error,pls set again",rect_idx);   
    }
    if(rect_grad_en){
        switch(rect_grad_mode) {
            case RECT_HORI_GRAD       : {rect_grad_mode_val  = 0;
                                         delta_r             = get_rect_delta(step_r,rect_width,color_r_delta);
                                         delta_g             = get_rect_delta(step_g,rect_width,color_g_delta);
                                         delta_b             = get_rect_delta(step_b,rect_width,color_b_delta);
            break;}
            case RECT_HORI_CENTER_GRAD: {rect_grad_mode_val  = 1;
                                         delta_r             = get_rect_delta(step_r,rect_width,color_r_delta);
                                         delta_g             = get_rect_delta(step_g,rect_width,color_g_delta);
                                         delta_b             = get_rect_delta(step_b,rect_width,color_b_delta);
            break;}
            case RECT_VERT_GRAD       : {rect_grad_mode_val  = 2;
                                         delta_r             = get_rect_delta(step_r,rect_height,color_r_delta);
                                         delta_g             = get_rect_delta(step_g,rect_height,color_g_delta);
                                         delta_b             = get_rect_delta(step_b,rect_height,color_b_delta);
            break;}
            case RECT_VERT_CENTER_GRAD: {rect_grad_mode_val  = 3;
                                         delta_r             = get_rect_delta(step_r,rect_height,color_r_delta);
                                         delta_g             = get_rect_delta(step_g,rect_height,color_g_delta);
                                         delta_b             = get_rect_delta(step_b,rect_height,color_b_delta);
            break;}
            case RECT_BILA_CENTER_GRAD: {rect_grad_mode_val  = 4;
                                         delta_r             = get_rect_delta(step_r,rect_length,color_r_delta);
                                         delta_g             = get_rect_delta(step_g,rect_length,color_g_delta);
                                         delta_b             = get_rect_delta(step_b,rect_length,color_b_delta);
            break;}
            case RECT_PURE            : {rect_grad_mode_val  = 5;
            break;}
        } 
    }
    else {
        rect_line_thick = rect_thick;
    }
    uint32_t  rect_mode_info = (rect_grad_mode<<8)|(rect_mode<<7)|(rect_line_thick<<3)|(comp_r<<2)|(comp_g<<1)|comp_b;
    Wr_reg_bits(rect_mode_addr,rect_mode_info,0,11);
    Wr(rect_delta_addr,(delta_r<<16)|(delta_g<<8)|delta_b);
    Wr(rect_step_addr,(step_r<<16)|(step_g<<8)|step_b);
    Wr(rect_color_addr,(rect_alpha<<24)|(rect_st_r<<16)|(rect_st_g<<8)|rect_st_b);
};

int get_rect_delta(int rect_step_level, int rect_width , int color_delta ){
    uint32_t rect_step  = (rect_width/*+rect_step_level-1*/) / rect_step_level;
    uint32_t rect_delta = (color_delta/*+rect_step_level-1*/)/ rect_step;                                 
    return rect_delta;
}

void cfg_ellip_en(int ellip_idx, uint8_t ellip_en , uint8_t ellip_mode){
    uint32_t ellip_addr =0;
    switch(ellip_idx) {
        case 0: ellip_addr = FOSD_ELLIP_INFO_0; break;
        case 1: ellip_addr = FOSD_ELLIP_INFO_1; break;
        default: printf("[cfg_ellip_en] :ellip_idx [%d] error,pls set again",ellip_idx);   
    }
    Wr_reg_bits(ellip_addr,(ellip_en<<1)|ellip_mode,24,2);
};

void cfg_ellip_position(int ellip_idx, int ellip_center_x, int ellip_center_y,int ellip_line_width, int ellip_hradius, int ellip_vradius){
    uint64_t ellip_outer_hradius_square        = ellip_hradius*ellip_hradius; 
    uint64_t ellip_inter_hradius_square        = (ellip_hradius-ellip_line_width)*(ellip_hradius-ellip_line_width); 
    uint64_t ellip_outer_vradius_square        = ellip_vradius*ellip_vradius; 
    uint64_t ellip_inter_vradius_square        = (ellip_vradius-ellip_line_width)*(ellip_vradius-ellip_line_width); 
    uint64_t ellip_outer_hradius_square_square = ellip_outer_hradius_square* ellip_outer_vradius_square;
    uint64_t ellip_inter_hradius_square_square = ellip_inter_hradius_square* ellip_inter_vradius_square;
    uint32_t ellip_outer_hradius_square_square_low_32 = ellip_outer_hradius_square_square & 0xffffffff;
    uint32_t ellip_outer_hradius_square_square_hign_8 = ellip_outer_hradius_square_square >>32;
    uint32_t ellip_inter_hradius_square_square_low_32 = ellip_inter_hradius_square_square & 0xffffffff;
    uint32_t ellip_inter_hradius_square_square_hign_8 = ellip_inter_hradius_square_square >>32;
    if(ellip_idx==0){
    printf("[OSD DEBUG]:++++++++++++++++++++++src o %d i %d  o %d i %d \n",ellip_outer_hradius_square_square,ellip_inter_hradius_square_square,ellip_outer_hradius_square_square_hign_8,ellip_inter_hradius_square_square_hign_8);
    }
    uint32_t ellip_idx_addr            =0;
    uint32_t ellip_info_addr           =0;
    uint32_t ellip_hradius_addr_out0   =0;
    uint32_t ellip_hradius_addr_in0    =0;
    uint32_t ellip_hradius_addr_out1   =0;
    uint32_t ellip_hradius_addr_in1    =0;
    uint32_t ellip_out_radius_addr_l   =0;
    uint32_t ellip_in_radius_addr_l    =0;
    uint32_t ellip_outin_radius_addr_h =0;

    switch(ellip_idx) {
        case 0: {ellip_idx_addr             = FOSD_ELLIP_CENTERXY_0     ;
                 ellip_info_addr            = FOSD_ELLIP_INFO_0         ; 
                 ellip_hradius_addr_out0    = FOSD_ELLIP_OUT_A2_0       ; 
                 ellip_hradius_addr_in0     = FOSD_ELLIP_IN_A2_0        ; 
                 ellip_hradius_addr_out1    = FOSD_ELLIP_OUT_B2_0       ; 
                 ellip_hradius_addr_in1     = FOSD_ELLIP_IN_B2_0        ;  
                 ellip_out_radius_addr_l    = FOSD_ELLIP_OUT_A2B2_L_0   ;
                 ellip_in_radius_addr_l     = FOSD_ELLIP_IN_A2B2_L_0    ;
                 ellip_outin_radius_addr_h  = FOSD_ELLIP_OUTIN_A2B2_H_0 ;
        break;}
        case 1: {ellip_idx_addr             = FOSD_ELLIP_CENTERXY_1     ;
                 ellip_info_addr            = FOSD_ELLIP_INFO_1         ; 
                 ellip_hradius_addr_out0    = FOSD_ELLIP_OUT_A2_1       ; 
                 ellip_hradius_addr_in0     = FOSD_ELLIP_IN_A2_1        ; 
                 ellip_hradius_addr_out1    = FOSD_ELLIP_OUT_B2_1       ; 
                 ellip_hradius_addr_in1     = FOSD_ELLIP_IN_B2_1        ;
                 ellip_out_radius_addr_l    = FOSD_ELLIP_OUT_A2B2_L_1   ;
                 ellip_in_radius_addr_l     = FOSD_ELLIP_IN_A2B2_L_1    ;
                 ellip_outin_radius_addr_h  = FOSD_ELLIP_OUTIN_A2B2_H_1 ;

        break;}
        default: printf("[cfg_ellip_position] ellip_idx [%d] error,pls set again",ellip_idx);   
    }
    Wr(ellip_idx_addr ,(ellip_center_x<<13)|(ellip_center_y<<0));
    Wr_reg_bits(ellip_info_addr,(ellip_line_width<<20)|(ellip_hradius<<10)|ellip_vradius,0,24);
    Wr(ellip_hradius_addr_out0,ellip_outer_hradius_square);
    Wr(ellip_hradius_addr_in0 ,ellip_inter_hradius_square);
    Wr(ellip_hradius_addr_out1,ellip_outer_vradius_square);
    Wr(ellip_hradius_addr_in1 ,ellip_inter_vradius_square);
    Wr(ellip_out_radius_addr_l,ellip_outer_hradius_square_square_low_32);
    Wr(ellip_in_radius_addr_l ,ellip_inter_hradius_square_square_low_32);
    Wr(ellip_outin_radius_addr_h,(ellip_inter_hradius_square_square_hign_8<<8)|ellip_outer_hradius_square_square_hign_8);

}; 
void cfg_ellip_color(int ellip_idx, int ellip_color_r, int ellip_color_g, int ellip_color_b, int ellip_alpha){
    uint32_t ellip_color_addr        =0;
    switch(ellip_idx) {
        case 0: {ellip_color_addr         = FOSD_ELLIP_RGBA_0;
        break;}
        case 1: {ellip_color_addr         = FOSD_ELLIP_RGBA_1;
        break;}
        default: printf("[cfg_ellip_color] ellip_idx [%d] error,pls set again",ellip_idx);   
    }
    Wr(ellip_color_addr ,(ellip_alpha<<24)|(ellip_color_r<<16)|(ellip_color_g<<8)|ellip_color_b);
}; 

void cfg_line_en(int line_idx, uint8_t line_en ){
    uint32_t line_addr =0;
    switch(line_idx) {
        case 0: line_addr = FOSD_LINE_START_XY_0; break;
        case 1: line_addr = FOSD_LINE_START_XY_1; break;
        case 2: line_addr = FOSD_LINE_START_XY_2; break;
        case 3: line_addr = FOSD_LINE_START_XY_3; break;
        case 4: line_addr = FOSD_LINE_START_XY_4; break;
        default: printf("[cfg_line_en] :line_idx [%d] error,pls set again",line_idx);   
    }
    Wr_reg_bits(line_addr,line_en,4,1);
};
void cfg_line_position(int line_idx, int line_st_x, int line_st_y, int line_ed_x, int line_ed_y,int line_width){
    uint32_t line_grad               = get_line_k_abs(line_st_x,line_st_y,line_ed_x,line_ed_y);
    uint32_t line_st_idx_addr        =0;
    uint32_t line_ed_idx_addr        =0;
    uint32_t line_grad_addr          =0;
    uint32_t line_width_addr         =0;
    switch(line_idx) {
        case 0: {line_st_idx_addr    = FOSD_LINE_START_XY_0;
                 line_ed_idx_addr    = FOSD_LINE_END_XY_0  ; 
                 line_grad_addr      = FOSD_LINE_K_0       ; 
                // line_width_addr     = FOSD_LINE_START_XY_0; 
        break;}
        case 1: {line_st_idx_addr    = FOSD_LINE_START_XY_1;
                 line_ed_idx_addr    = FOSD_LINE_END_XY_1  ; 
                 line_grad_addr      = FOSD_LINE_K_1       ; 
                // line_width_addr     = FOSD_MODE_INFO_1_1  ; 
        break;}
        case 2: {line_st_idx_addr    = FOSD_LINE_START_XY_2;
                 line_ed_idx_addr    = FOSD_LINE_END_XY_2  ; 
                 line_grad_addr      = FOSD_LINE_K_2       ; 
                // line_width_addr     = FOSD_MODE_INFO_1_2  ; 
        break;}
        case 3: {line_st_idx_addr    = FOSD_LINE_START_XY_3;
                 line_ed_idx_addr    = FOSD_LINE_END_XY_3  ; 
                 line_grad_addr      = FOSD_LINE_K_3       ; 
                // line_width_addr     = FOSD_MODE_INFO_1_3  ; 
        break;}
        case 4: {line_st_idx_addr    = FOSD_LINE_START_XY_4;
                 line_ed_idx_addr    = FOSD_LINE_END_XY_4  ; 
                 line_grad_addr      = FOSD_LINE_K_4       ; 
                // line_width_addr     = FOSD_MODE_INFO_1_4  ; 
        break;}
        default: printf("[cfg_line_position] line_idx [%d] error,pls set again",line_idx);   
    }
    uint32_t line_st_idx_info = Rd(line_st_idx_addr);
             line_st_idx_info = (line_st_x<<18)|(line_st_y<<5)|line_st_idx_info|(line_width & 0xf);
             
    Wr(line_st_idx_addr ,line_st_idx_info);
    Wr(line_ed_idx_addr ,(line_ed_x<<13)|(line_ed_y<<0));
    Wr(line_grad_addr   ,line_grad                     );
    //Wr_reg_bits(line_width_addr,line_width,11,4);
}; 
void cfg_line_color(int line_idx, int line_color_r, int line_color_g, int line_color_b, int line_alpha){
    uint32_t line_color_addr        =0;
    switch(line_idx) {
        case 0: {line_color_addr         = FOSD_LINE_RGBA_0;
        break;}
        case 1: {line_color_addr         = FOSD_LINE_RGBA_1;
        break;}
        case 2: {line_color_addr         = FOSD_LINE_RGBA_2;
        break;}
        case 3: {line_color_addr         = FOSD_LINE_RGBA_3;
        break;}
        case 4: {line_color_addr         = FOSD_LINE_RGBA_4;
        break;}
        default: printf("[cfg_line_color] line_idx [%d] error,pls set again",line_idx);   
    }
    Wr(line_color_addr ,(line_alpha<<24)|(line_color_r<<16)|(line_color_g<<8)|line_color_b);
}; 

int get_line_k_abs (int line_st_x, int line_st_y, int line_ed_x, int line_ed_y)
{
    uint32_t dx   = abs(line_ed_x - line_st_x);
    uint32_t dy   = abs(line_ed_y - line_st_y);
    uint8_t     dx_max_dy = (dx > dy) ? 1 :0 ;
    uint32_t dy_new = dx_max_dy ? dy : dx;
    uint32_t dx_new = dx_max_dy ? dx : dy;
    uint32_t grad = dx_new ==0 ? 1<<16 : (dy_new<<16)/dx_new;//dx > dy ? (dy<<16)/dx :(dx<<16)/dy 
    return grad;
} 
void cfg_font_repack(MNT_OSD_FONT_REPACK_t *osd_font_repack_info)
{
    if(osd_font_repack_info->osd_font_rep_en==1){
        uint8_t  osd_font_gap= osd_font_repack_info->osd_font_gap;
        uint8_t  osd_font_nrep_num = osd_font_repack_info->osd_font_nrep_num;
        uint8_t  osd_font_rep_num = osd_font_repack_info->osd_font_rep_num;
        uint32_t osd_font_rep_st_addr[FOSD_FONT_REP_NUM];
        uint32_t osd_font_rep_sum_num[FOSD_FONT_REP_NUM];
        uint32_t osd_font_nrep_st_addr[FOSD_FONT_REP_NUM];
        uint32_t osd_font_nrep_sum_num[FOSD_FONT_REP_NUM];
        cfg_font_repack_gap(osd_font_gap);        
        for(int i=0;i<FOSD_FONT_REP_NUM;i++){
            osd_font_rep_st_addr[i]= osd_font_repack_info->osd_font_rep_st_addr[i];
            osd_font_rep_sum_num[i]= osd_font_repack_info->osd_font_rep_sum_num[i];
            osd_font_nrep_st_addr[i]= osd_font_repack_info->osd_font_nrep_st_addr[i];
            osd_font_nrep_sum_num[i]= osd_font_repack_info->osd_font_nrep_sum_num[i];
            if(i<osd_font_nrep_num){
                read_font_to_mem(font_1b_arr,osd_font_nrep_st_addr[i],osd_font_nrep_sum_num[i]);                
            }
            if(i<osd_font_rep_num){
                cfg_font_repack_mode(1);  
                switch(i){
                    case 0 : read_font_to_mem(osd_1b_font_repack_arr0,osd_font_rep_st_addr[i],osd_font_rep_sum_num[i]);break; 
                    case 1 : read_font_to_mem(osd_1b_font_repack_arr1,osd_font_rep_st_addr[i],osd_font_rep_sum_num[i]);break; 
                    case 2 : read_font_to_mem(osd_1b_font_repack_arr2,osd_font_rep_st_addr[i],osd_font_rep_sum_num[i]);break; 
                    case 3 : read_font_to_mem(osd_1b_font_repack_arr3,osd_font_rep_st_addr[i],osd_font_rep_sum_num[i]);break; 
                    case 4 : read_font_to_mem(osd_1b_font_repack_arr4,osd_font_rep_st_addr[i],osd_font_rep_sum_num[i]);break; 
                    default: printf("[cfg_font_repack] :arr [%d] error,have arr[%d],pls set again",i,osd_font_rep_num);  
                }      
                cfg_font_repack_mode(0);        
            }
        }
    }
}
void cfg_font_repack_mode(uint8_t repack_en )
{
    uint32_t font_repack_addr     = FOSD_FONT_REPACK_CTRL;
    Wr(font_repack_addr,repack_en);
}
void cfg_font_repack_gap(uint8_t font_gap)
{
    uint32_t font_repack_gap_addr = FOSD_FONT_REPACK_GAP;
    if(font_gap>0xf){
        printf("[cfg_font_repack_mode] font_gap [%d] error,need[0-f],pls set again",font_gap);
    }
    Wr(font_repack_gap_addr,font_gap);
}
void upd_init_arr(MNT_OSD_FONT_TYPE_t sel, uint32_t *arr )
{   
    switch(sel) {
        case FONT_TYPE_1B :   memcpy(font_1b_arr     ,arr,sizeof(arr))    ; break;
        case FONT_TYPE_2B :   memcpy(font_2b_arr     ,arr,sizeof(arr))    ; break;
        case FONT_TYPE_4B :   memcpy(font_4b_arr     ,arr,sizeof(arr))    ; break;
        case WIN0_TYPE_IDX:   memcpy(osd_win0_idx_arr,arr,sizeof(arr))   ; break;
        case WIN1_TYPE_IDX:   memcpy(osd_win1_idx_arr,arr,sizeof(arr))   ; break;
        case WIN2_TYPE_IDX:   memcpy(osd_win2_idx_arr,arr,sizeof(arr))   ; break;
        case WIN3_TYPE_IDX:   memcpy(osd_win3_idx_arr,arr,sizeof(arr))   ; break;
        case WIN4_TYPE_IDX:   memcpy(osd_win4_idx_arr,arr,sizeof(arr))   ; break;
        case WIN5_TYPE_IDX:   memcpy(osd_win5_idx_arr,arr,sizeof(arr))   ; break;
        case WIN6_TYPE_IDX:   memcpy(osd_win6_idx_arr,arr,sizeof(arr))   ; break;
        case WIN7_TYPE_IDX:   memcpy(osd_win7_idx_arr,arr,sizeof(arr))   ; break;
        case FONT_TYPE_REP0:   memcpy(osd_1b_font_repack_arr0,arr,sizeof(arr))   ; break;
        case FONT_TYPE_REP1:   memcpy(osd_1b_font_repack_arr1,arr,sizeof(arr))   ; break;
        case FONT_TYPE_REP2:   memcpy(osd_1b_font_repack_arr2,arr,sizeof(arr))   ; break;
        case FONT_TYPE_REP3:   memcpy(osd_1b_font_repack_arr3,arr,sizeof(arr))   ; break;
        case FONT_TYPE_REP4:   memcpy(osd_1b_font_repack_arr4,arr,sizeof(arr))   ; break;
        default: printf("[upd_init_arr] :arr [%d] error,pls set again",sel);  
    }      
}
